Here is a simple Python script for asynchronous task scheduling using a CommandQueue.

```python
from typing import Any, Optional, Callable

import os

class CommandQueue:
    def __init__(self, max_queue_size: int = 100):
        self.max_queue_size = max_queue_size
        self.tasks = []

    def schedule(self, func):
        """Schedule a function to execute later."""
        self.tasks.append(func)

    def run(self, *, name):
        """Run tasks synchronously."""
        next_waits = []
        while True:
            func = self.tasks.pop(0)
            func()
            if not func:
                break
            self.schedule(func)

    def run_async(self, func, name=''):
        """Asynchronous execution."""
        def inner_timer():
            import time
            time.sleep(0.01)
            func()
            return None
        timer = self.timer(inner_timer)
        self.schedule(func, name=name)
        return func()

    def timer(self, func):
        '''Schedule a function to run at time intervals.'''
        start = os.time()
        try:
            func()
            elapsed = os.time() - start
        finally:
            print(f"Function {func} completed at {elapsed:.6f}s.")
        return elapsed

class WeeklyTaskScheduler:
    """A command queue that executes tasks weekly."""

    def __init__(self):
        self._queue = CommandQueue(max_queue_size=20)
        self._current_time = None

    def schedule_task(self, func):
        """Schedule a specific function every Sunday."""
        self._queue.schedule(func)

    def run(self, *, name=''):
        """Run a scheduled task."""
        self._queue.run(name=name)

    def add_task(self, func):
        """Add a task to the queue."""
        self._queue.schedule(func)
        self._current_time = os.time()

    def complete(self):
        """Ensure the queue operates as expected."""
        pass

def run_some_tasks():
    """Show how tasks propagate."""
    que = WeeklyTaskScheduler()
    tasks = que.get_weekly_tasks()
    print(f"Weekly tasks running: {len(tasks)}")

